#include <stdio.h>



int main(void) {
    long long m, n, a, b;
    scanf("%lld%lld", &m, &n);
    a = m; b = n;
    while (b) { long long r = a % b; a = b; b = r; }
    printf("%lld %lld\n", a, m / a * n);
    return 0;
}
